begin;

create or replace function pg_temp.pma_figure(p_code text)
returns jsonb
language plpgsql
as $$
declare v_shapes jsonb := '[]'::jsonb;
declare v_token text;
declare v_shape jsonb;
begin
  foreach v_token in array regexp_split_to_array(p_code, '\+') loop
    v_shape := case v_token
      when 'circle' then jsonb_build_object('type','circle','cx',50,'cy',50,'r',25,'fill','none','stroke','#cbd5e1')
      when 'square' then jsonb_build_object('type','rect','x',25,'y',25,'width',50,'height',50,'fill','none','stroke','#cbd5e1','strokeWidth',3)
      when 'tri-up' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',50,'y',18),jsonb_build_object('x',82,'y',78),jsonb_build_object('x',18,'y',78)),'fill','none','stroke','#cbd5e1')
      when 'tri-right' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',82,'y',50),jsonb_build_object('x',22,'y',18),jsonb_build_object('x',22,'y',82)),'fill','none','stroke','#cbd5e1')
      when 'tri-down' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',50,'y',82),jsonb_build_object('x',18,'y',22),jsonb_build_object('x',82,'y',22)),'fill','none','stroke','#cbd5e1')
      when 'tri-left' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',18,'y',50),jsonb_build_object('x',78,'y',82),jsonb_build_object('x',78,'y',18)),'fill','none','stroke','#cbd5e1')
      when 'diamond' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',50,'y',15),jsonb_build_object('x',85,'y',50),jsonb_build_object('x',50,'y',85),jsonb_build_object('x',15,'y',50)),'fill','none','stroke','#cbd5e1')
      when 'small-diamond' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',50,'y',38),jsonb_build_object('x',62,'y',50),jsonb_build_object('x',50,'y',62),jsonb_build_object('x',38,'y',50)),'fill','none','stroke','#cbd5e1')
      when 'pentagon' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',50,'y',12),jsonb_build_object('x',86,'y',38),jsonb_build_object('x',72,'y',82),jsonb_build_object('x',28,'y',82),jsonb_build_object('x',14,'y',38)),'fill','none','stroke','#cbd5e1')
      when 'hexagon' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',50,'y',10),jsonb_build_object('x',84,'y',30),jsonb_build_object('x',84,'y',70),jsonb_build_object('x',50,'y',90),jsonb_build_object('x',16,'y',70),jsonb_build_object('x',16,'y',30)),'fill','none','stroke','#cbd5e1')
      when 'heptagon' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',50,'y',10),jsonb_build_object('x',82,'y',24),jsonb_build_object('x',90,'y',58),jsonb_build_object('x',68,'y',86),jsonb_build_object('x',32,'y',86),jsonb_build_object('x',10,'y',58),jsonb_build_object('x',18,'y',24)),'fill','none','stroke','#cbd5e1')
      when 'hexagon-rotated' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',78,'y',22),jsonb_build_object('x',88,'y',60),jsonb_build_object('x',60,'y',88),jsonb_build_object('x',22,'y',78),jsonb_build_object('x',12,'y',40),jsonb_build_object('x',40,'y',12)),'fill','none','stroke','#cbd5e1')
      when 'small-hexagon' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',50,'y',34),jsonb_build_object('x',64,'y',42),jsonb_build_object('x',64,'y',58),jsonb_build_object('x',50,'y',66),jsonb_build_object('x',36,'y',58),jsonb_build_object('x',36,'y',42)),'fill','none','stroke','#cbd5e1')
      when 'dot-nw' then jsonb_build_object('type','circle','cx',25,'cy',25,'r',8,'fill','#34d399','stroke','#34d399')
      when 'dot-ne' then jsonb_build_object('type','circle','cx',75,'cy',25,'r',8,'fill','#34d399','stroke','#34d399')
      when 'dot-se' then jsonb_build_object('type','circle','cx',75,'cy',75,'r',8,'fill','#34d399','stroke','#34d399')
      when 'dot-sw' then jsonb_build_object('type','circle','cx',25,'cy',75,'r',8,'fill','#34d399','stroke','#34d399')
      when 'dot-center' then jsonb_build_object('type','circle','cx',50,'cy',50,'r',8,'fill','#34d399','stroke','#34d399')
      when 'dot-top' then jsonb_build_object('type','circle','cx',50,'cy',18,'r',8,'fill','#34d399','stroke','#34d399')
      when 'dot-right' then jsonb_build_object('type','circle','cx',82,'cy',50,'r',8,'fill','#34d399','stroke','#34d399')
      when 'dot-bottom' then jsonb_build_object('type','circle','cx',50,'cy',82,'r',8,'fill','#34d399','stroke','#34d399')
      when 'dot-left' then jsonb_build_object('type','circle','cx',18,'cy',50,'r',8,'fill','#34d399','stroke','#34d399')
      when 'dot-pent-ne' then jsonb_build_object('type','circle','cx',86,'cy',38,'r',7,'fill','#34d399','stroke','#34d399')
      when 'dot-pent-se' then jsonb_build_object('type','circle','cx',72,'cy',82,'r',7,'fill','#34d399','stroke','#34d399')
      when 'dot-pent-sw' then jsonb_build_object('type','circle','cx',28,'cy',82,'r',7,'fill','#34d399','stroke','#34d399')
      when 'dot-pent-nw' then jsonb_build_object('type','circle','cx',14,'cy',38,'r',7,'fill','#34d399','stroke','#34d399')
      when 'dot-square-ne' then jsonb_build_object('type','circle','cx',80,'cy',20,'r',7,'fill','#34d399','stroke','#34d399')
      when 'dot-hex-ne' then jsonb_build_object('type','circle','cx',84,'cy',30,'r',7,'fill','#34d399','stroke','#34d399')
      when 'dot-hex-se' then jsonb_build_object('type','circle','cx',84,'cy',70,'r',7,'fill','#34d399','stroke','#34d399')
      when 'small-circle' then jsonb_build_object('type','circle','cx',50,'cy',50,'r',9,'fill','none','stroke','#cbd5e1')
      when 'tiny-circle' then jsonb_build_object('type','circle','cx',50,'cy',50,'r',4,'fill','none','stroke','#cbd5e1')
      when 'mini-circle' then jsonb_build_object('type','circle','cx',50,'cy',50,'r',2,'fill','none','stroke','#cbd5e1')
      when 'small-square' then jsonb_build_object('type','rect','x',40,'y',40,'width',20,'height',20,'fill','none','stroke','#cbd5e1')
      when 'small-north' then jsonb_build_object('type','rect','x',44,'y',14,'width',12,'height',12,'fill','none','stroke','#cbd5e1')
      when 'small-east' then jsonb_build_object('type','rect','x',74,'y',44,'width',12,'height',12,'fill','none','stroke','#cbd5e1')
      when 'small-south' then jsonb_build_object('type','rect','x',44,'y',74,'width',12,'height',12,'fill','none','stroke','#cbd5e1')
      when 'small-west' then jsonb_build_object('type','rect','x',14,'y',44,'width',12,'height',12,'fill','none','stroke','#cbd5e1')
      when 'bar-h' then jsonb_build_object('type','line','x1',18,'y1',50,'x2',82,'y2',50,'stroke','#cbd5e1','strokeWidth',5)
      when 'bar-v' then jsonb_build_object('type','line','x1',50,'y1',18,'x2',50,'y2',82,'stroke','#cbd5e1','strokeWidth',5)
      when 'seg-top-h' then jsonb_build_object('type','line','x1',30,'y1',30,'x2',70,'y2',30,'stroke','#cbd5e1','strokeWidth',5)
      when 'seg-right-v' then jsonb_build_object('type','line','x1',70,'y1',30,'x2',70,'y2',70,'stroke','#cbd5e1','strokeWidth',5)
      when 'seg-bottom-h' then jsonb_build_object('type','line','x1',30,'y1',70,'x2',70,'y2',70,'stroke','#cbd5e1','strokeWidth',5)
      when 'seg-left-v' then jsonb_build_object('type','line','x1',30,'y1',30,'x2',30,'y2',70,'stroke','#cbd5e1','strokeWidth',5)
      when 'slash' then jsonb_build_object('type','line','x1',20,'y1',80,'x2',80,'y2',20,'stroke','#cbd5e1','strokeWidth',5)
      when 'backslash' then jsonb_build_object('type','line','x1',20,'y1',20,'x2',80,'y2',80,'stroke','#cbd5e1','strokeWidth',5)
      when 'corner-nw' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',20,'y',20),jsonb_build_object('x',80,'y',20),jsonb_build_object('x',20,'y',80)),'fill','none','stroke','#cbd5e1')
      when 'corner-ne' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',20,'y',20),jsonb_build_object('x',80,'y',20),jsonb_build_object('x',80,'y',80)),'fill','none','stroke','#cbd5e1')
      when 'corner-se' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',80,'y',20),jsonb_build_object('x',80,'y',80),jsonb_build_object('x',20,'y',80)),'fill','none','stroke','#cbd5e1')
      when 'corner-sw' then jsonb_build_object('type','polygon','points',jsonb_build_array(jsonb_build_object('x',20,'y',20),jsonb_build_object('x',80,'y',80),jsonb_build_object('x',20,'y',80)),'fill','none','stroke','#cbd5e1')
      else null
    end;
    if v_shape is null then
      raise exception 'Unknown PMA visual figure code: %', v_token;
    end if;
    v_shapes := v_shapes || jsonb_build_array(v_shape);
  end loop;
  return jsonb_build_object('shapes', v_shapes);
end;
$$;

create or replace function pg_temp.pma_visual(p_prompt text[], p_options text[])
returns jsonb
language sql
as $$
  select jsonb_build_object(
    'prompt', (
      select jsonb_agg(case when figure_code = '?' then 'null'::jsonb else pg_temp.pma_figure(figure_code) end order by ordinal)
      from unnest(p_prompt) with ordinality as prompt(figure_code, ordinal)
    ),
    'options', (
      select jsonb_agg(pg_temp.pma_figure(figure_code) order by ordinal)
      from unnest(p_options) with ordinality as options(figure_code, ordinal)
    )
  );
$$;

insert into public.mock_tests (title, slug, description, branch_id, exam_id, duration_minutes, total_questions, difficulty, is_premium, is_active, category)
select seed.title, seed.slug, seed.description, branch.id, exam.id, seed.duration_minutes, 50, 'MEDIUM', false, true, seed.category
from (values
  ('PMA Long Course Initial Test — Verbal Intelligence Test 1', 'pma-verbal-intelligence-test-1', 'Original verbal intelligence practice: mixed series, coding, classification, logic and orientation.', 'Verbal Intelligence', 25),
  ('PMA Long Course Initial Test — Verbal Intelligence Test 2', 'pma-verbal-intelligence-test-2', 'Original verbal intelligence practice with varied reasoning structures and a gradual difficulty curve.', 'Verbal Intelligence', 25),
  ('PMA Long Course Initial Test — Verbal Intelligence Test 3', 'pma-verbal-intelligence-test-3', 'Independent mixed verbal reasoning practice for PMA Long Course preparation.', 'Verbal Intelligence', 25),
  ('PMA Long Course Initial Test — Non-Verbal Intelligence Test 1', 'pma-non-verbal-intelligence-test-1', 'Structured figure-series, transformation and spatial reasoning practice.', 'Non-Verbal Intelligence', 25),
  ('PMA Long Course Initial Test — Non-Verbal Intelligence Test 2', 'pma-non-verbal-intelligence-test-2', 'Independent structured visual reasoning practice with matrices and spatial transformations.', 'Non-Verbal Intelligence', 25),
  ('PMA Long Course Initial Test — Non-Verbal Intelligence Test 3', 'pma-non-verbal-intelligence-test-3', 'Independent visual classification, reflection, counting and pattern reasoning practice.', 'Non-Verbal Intelligence', 25),
  ('PMA Long Course Initial Test — Analogy Test', 'pma-analogy-test', 'Dedicated word, function, part-whole, numeric and alphabetic analogy practice.', 'Analogy', 25),
  ('PMA Long Course Initial Test — Mathematical Series Test', 'pma-mathematical-series-test', 'Dedicated mathematical sequence practice across arithmetic, alternating and power patterns.', 'Mathematical Series', 25)
) as seed(title, slug, description, category, duration_minutes)
join public.military_branches branch on branch.slug = 'pak-army'
join public.exams exam on exam.slug = 'pma-long-course-initial-test'
on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  branch_id = excluded.branch_id,
  exam_id = excluded.exam_id,
  duration_minutes = excluded.duration_minutes,
  total_questions = 50,
  difficulty = excluded.difficulty,
  is_premium = false,
  is_active = true,
  category = excluded.category,
  updated_at = now();

create temporary table pma_seed_questions on commit drop as
with raw_questions(paper_slug, question_number, topic_slug, question_text, difficulty, priority, option_a, option_b, option_c, option_d, correct_option, explanation, visual_data) as (
values
('pma-verbal-intelligence-test-1',1,'pma-letter-series','Complete the circular alphabet series: C, F, K, R, ?', 'EASY','HIGH','A','W','X','Y','A','The letter positions advance by +3, +5, then +7. The next jump is +9: 18 + 9 = 27; after Z, the circular alphabet returns to A.','null'::jsonb),
('pma-verbal-intelligence-test-1',2,'pma-letter-series','Moving backward through the alphabet, what comes next: Z, X, U, Q, ?', 'EASY','HIGH','L','M','N','O','A','The backward steps are 2, 3, and 4 letters. The next step is 5: Q moves back five places to L.','null'::jsonb),
('pma-verbal-intelligence-test-1',3,'pma-letter-series','Find the next letter: A, D, C, F, E, H, ?', 'EASY','HIGH','G','I','J','K','A','Two sequences are interleaved: positions 1, 3, 5, 7 are A, C, E, G; positions 2, 4, 6 are D, F, H. The next term is G.','null'::jsonb),
('pma-verbal-intelligence-test-1',4,'pma-letter-series','Complete the paired series: AZ, BY, CX, DW, ?', 'EASY','HIGH','EU','EV','FU','FV','B','The first letters move forward A, B, C, D, E while the second move backward Z, Y, X, W, V. The next pair is EV.','null'::jsonb),
('pma-verbal-intelligence-test-1',5,'pma-letter-series','Complete the letter series: A, D, H, M, S, ?', 'MEDIUM','HIGH','Y','Z','A','B','B','The forward increments are +3, +4, +5, and +6. Add +7 to S, wrapping past Z, to reach Z.','null'::jsonb),
('pma-verbal-intelligence-test-1',6,'pma-verbal-number-series','What number completes 6, 11, 19, 30, 44, ?', 'MEDIUM','HIGH','59','60','61','62','C','The successive increases are 5, 8, 11, and 14, rising by 3 each time. The next increase is 17, so 44 + 17 = 61.','null'::jsonb),
('pma-verbal-intelligence-test-1',7,'pma-verbal-number-series','What number follows the doubling sequence: 3, 6, 12, 24, 48, ?', 'MEDIUM','HIGH','72','84','96','108','C','Each term is multiplied by 2; 48×2=96.','null'::jsonb),
('pma-verbal-intelligence-test-1',8,'pma-verbal-number-series','Complete the alternating operation series: 2, 12, 6, 36, 18, 108, ?', 'MEDIUM','MEDIUM','48','54','60','216','B','The operations alternate ×6 and ÷2: 2×6=12, 12÷2=6, and 18×6=108. The next step is 108÷2=54.','null'::jsonb),
('pma-verbal-intelligence-test-1',9,'pma-verbal-number-series','What comes next: 3, 8, 18, 38, 78, ?', 'MEDIUM','HIGH','148','156','158','160','C','Each term is doubled and then 2 is added: 3×2+2=8, 8×2+2=18, and so on. Thus 78×2+2=158.','null'::jsonb),
('pma-verbal-intelligence-test-1',10,'pma-verbal-number-series','Complete the triangular-number sequence: 1, 3, 6, 10, 15, ?', 'MEDIUM','MEDIUM','18','20','21','24','C','Add consecutive integers: +2, +3, +4, +5. The next increase is +6, so 15+6=21.','null'::jsonb),
('pma-verbal-intelligence-test-1',11,'pma-coding-decoding','If each letter is shifted forward by 3 places, how is MARCH coded?', 'EASY','HIGH','PDUFK','PDUGK','QDUFK','PDSFK','A','Shift each letter three positions: M→P, A→D, R→U, C→F, H→K. The code is PDUFK.','null'::jsonb),
('pma-verbal-intelligence-test-1',12,'pma-coding-decoding','In a code, the first and last letters swap while the middle stays fixed. How is PLANE written?', 'EASY','MEDIUM','ELANP','ELNAP','EALNP','ELPNA','A','Swap only the endpoints of PLANE: P and E exchange places, giving ELANP.','null'::jsonb),
('pma-verbal-intelligence-test-1',13,'pma-coding-decoding','If a word is encoded by replacing each letter with its alphabet position, what is the code for MAP?', 'EASY','HIGH','13-1-16','12-1-16','13-2-16','13-1-15','A','M is the 13th letter, A is 1st, and P is 16th; therefore MAP is 13-1-16.','null'::jsonb),
('pma-verbal-intelligence-test-1',14,'pma-coding-decoding','A code reverses the order of letters. What does the code TSEW represent?', 'EASY','MEDIUM','WEST','WETS','SEWT','TEWS','A','Read the coded letters from right to left: TSEW reverses to WEST.','null'::jsonb),
('pma-verbal-intelligence-test-1',15,'pma-coding-decoding','Using opposite alphabet positions (A↔Z, B↔Y), how is BAD encoded?', 'MEDIUM','MEDIUM','YZW','YZX','XZW','YXV','A','B maps to Y, A maps to Z, and D maps to W under opposite-position substitution, giving YZW.','null'::jsonb),
('pma-verbal-intelligence-test-1',16,'pma-classification','Which item is not a close synonym of the others: swift, rapid, prompt, sluggish?', 'EASY','HIGH','Swift','Rapid','Prompt','Sluggish','D','Swift, rapid, and prompt all indicate speed or quickness. Sluggish means slow.','null'::jsonb),
('pma-verbal-intelligence-test-1',17,'pma-odd-one-out','Select the odd one out: copper, iron, silver, granite.', 'EASY','HIGH','Copper','Iron','Silver','Granite','D','Copper, iron, and silver are metals. Granite is a rock.','null'::jsonb),
('pma-verbal-intelligence-test-1',18,'pma-classification','Which instrument belongs with violin, cello, and viola?', 'EASY','MEDIUM','Double bass','Flute','Oboe','Trumpet','A','Violin, cello, viola, and double bass are bowed string instruments; the other choices are not.','null'::jsonb),
('pma-verbal-intelligence-test-1',19,'pma-odd-one-out','Choose the item that does not share the group rule: inch, metre, litre, centimetre.', 'MEDIUM','MEDIUM','Inch','Metre','Litre','Centimetre','C','Inch, metre, and centimetre measure length. A litre measures volume.','null'::jsonb),
('pma-verbal-intelligence-test-1',20,'pma-classification','Which word is the best category label for cedar, pine, and spruce?', 'EASY','MEDIUM','Deciduous trees','Conifers','Flowering shrubs','Grasses','B','Cedar, pine, and spruce are coniferous trees that typically bear cones.','null'::jsonb),
('pma-verbal-intelligence-test-1',21,'pma-word-relationship','Complete the relationship: seed is to plant as egg is to ___.', 'EASY','HIGH','Nest','Bird','Feather','Shell','B','A seed can develop into a plant; an egg can develop into a bird. Both relate an early life stage to the organism.','null'::jsonb),
('pma-verbal-intelligence-test-1',22,'pma-word-relationship','Complete the relationship: compass is to direction as thermometer is to ___.', 'EASY','HIGH','Pressure','Temperature','Distance','Speed','B','A compass indicates direction; a thermometer measures temperature.','null'::jsonb),
('pma-verbal-intelligence-test-1',23,'pma-word-relationship','Complete the relationship: author is to novel as composer is to ___.', 'EASY','MEDIUM','Instrument','Melody','Symphony','Audience','C','An author creates a novel; a composer creates a symphony.','null'::jsonb),
('pma-verbal-intelligence-test-1',24,'pma-word-relationship','Complete the relationship: bark is to tree as rind is to ___.', 'MEDIUM','MEDIUM','Fruit','Seed','Branch','Leaf','A','Bark is an outer covering of a tree; rind is an outer covering of certain fruits.','null'::jsonb),
('pma-verbal-intelligence-test-1',25,'pma-word-relationship','Choose the pair with the same relationship as question : answer.', 'MEDIUM','MEDIUM','Problem : solution','Book : page','Teacher : class','Clock : time','A','An answer resolves a question; a solution resolves a problem. The other pairs describe different associations.','null'::jsonb),
('pma-verbal-intelligence-test-1',26,'pma-sequence','Arrange these stages from earliest to latest: seed, sprout, sapling, mature tree.', 'EASY','HIGH','Seed, sprout, sapling, mature tree','Sprout, seed, mature tree, sapling','Sapling, sprout, seed, mature tree','Seed, sapling, sprout, mature tree','A','A plant begins as a seed, germinates as a sprout, grows into a sapling, then becomes mature.','null'::jsonb),
('pma-verbal-intelligence-test-1',27,'pma-sequence','Which order correctly describes sending a letter?', 'EASY','MEDIUM','Write, address, seal, post','Post, write, seal, address','Address, post, write, seal','Seal, post, address, write','A','The message is written, the envelope addressed, the letter sealed, and then it is posted.','null'::jsonb),
('pma-verbal-intelligence-test-1',28,'pma-sequence','Order these units from smallest to largest: paragraph, word, letter, sentence.', 'EASY','MEDIUM','Letter, word, sentence, paragraph','Word, letter, paragraph, sentence','Sentence, word, letter, paragraph','Letter, sentence, word, paragraph','A','Letters form words, words form sentences, and sentences form paragraphs.','null'::jsonb),
('pma-verbal-intelligence-test-1',29,'pma-sequence','A candidate ranks ahead of Bilal but behind Hadi. Who is between them?', 'EASY','MEDIUM','The candidate','Bilal','Hadi','Cannot be determined','A','The stated order is Hadi, candidate, Bilal. The candidate is between the other two.','null'::jsonb),
('pma-verbal-intelligence-test-1',30,'pma-sequence','Arrange from most general to most specific: vehicle, bicycle, transport, road bicycle.', 'MEDIUM','LOW','Transport, vehicle, bicycle, road bicycle','Vehicle, transport, road bicycle, bicycle','Bicycle, vehicle, transport, road bicycle','Transport, bicycle, vehicle, road bicycle','A','Transport is the broadest concept, then vehicle, then bicycle, then the specific road-bicycle type.','null'::jsonb),
('pma-verbal-intelligence-test-1',31,'pma-logical-reasoning','All pilots in a group passed a vision test. Sara is a pilot in that group. What follows?', 'EASY','HIGH','Sara passed the vision test','Sara is a doctor','Every person passed the test','Sara passed a hearing test','A','The universal statement applies to every pilot in the group, including Sara. No other conclusion is given.','null'::jsonb),
('pma-verbal-intelligence-test-1',32,'pma-logical-reasoning','Some recruits are left-handed. All left-handed recruits use the left-handed range. What must be true?', 'MEDIUM','HIGH','Every recruit uses that range','Some recruits use the left-handed range','No recruit uses the right-handed range','All range users are recruits','B','The recruits who are left-handed are included among those who use the left-handed range, so at least some recruits do.','null'::jsonb),
('pma-verbal-intelligence-test-1',33,'pma-logical-reasoning','No metal object is made of wood. This item is a wooden object. Which conclusion follows?', 'EASY','MEDIUM','It is not a metal object','It is a metal object','It must be plastic','Its weight is known','A','The premises exclude wooden objects from the class of metal objects. They do not identify its other properties.','null'::jsonb),
('pma-verbal-intelligence-test-1',34,'pma-logical-reasoning','A, B, and C stand in a line. A is ahead of B; C is behind B. Who is first?', 'EASY','MEDIUM','A','B','C','Cannot be determined','A','A is ahead of B and B is ahead of C, so the order is A, B, C.','null'::jsonb),
('pma-verbal-intelligence-test-1',35,'pma-logical-reasoning','A rule says every complete file has a signature. This file has no signature. What is the safest conclusion?', 'MEDIUM','MEDIUM','The file is not complete','The file is complete','The signature is optional','The file is invalid for every purpose','A','If complete implies signed, then lacking a signature means the file cannot be complete. No broader consequence is specified.','null'::jsonb),
('pma-verbal-intelligence-test-1',36,'pma-word-formation','Which word can be made using every letter in LISTEN exactly once?', 'MEDIUM','MEDIUM','Silent','Listenings','Tinselwood','Enlistment','A','SILENT uses the letters L, I, S, T, E, N once each, exactly matching LISTEN.','null'::jsonb),
