('pma-analogy-test',39,'pma-functional-analogy','Semaphore : Flags :: Morse : ?', 'MEDIUM','LOW','Dots and dashes','Radio tower','Alphabet','Cipher wheel','A','Semaphore communicates with flag positions; Morse code communicates with combinations of dots and dashes.','null'::jsonb),
('pma-analogy-test',40,'pma-relationship-analogy','Analogy : Correspondence :: Sequence : ?', 'MEDIUM','MEDIUM','Order','Similarity','Answer','Comparison','A','An analogy is organized around a correspondence between relationships; a sequence is organized by an order of terms.','null'::jsonb),
('pma-analogy-test',41,'pma-functional-analogy','Catalyst : Reaction :: Enzyme : ?', 'MEDIUM','MEDIUM','Biochemical Process','Substrate','Cell','Temperature','A','A catalyst speeds a chemical reaction; an enzyme speeds a biochemical process.','null'::jsonb),
('pma-analogy-test',42,'pma-functional-analogy','Parentheses : Aside :: Quotation Marks : ?', 'MEDIUM','LOW','Direct Speech','Question','Heading','Footnote','A','Parentheses can enclose an aside; quotation marks can enclose direct speech.','null'::jsonb),
('pma-analogy-test',43,'pma-functional-analogy','Larynx : Voice :: Diaphragm : ?', 'MEDIUM','MEDIUM','Breathing','Digestion','Hearing','Balance','A','The larynx enables voice production; the diaphragm is a key muscle used in breathing.','null'::jsonb),
