('pma-analogy-test',45,'pma-number-analogy','7 : 49 :: 9 : ?', 'EASY','HIGH','72','81','90','99','B','The output is the input squared: 7²=49, so 9²=81.','null'::jsonb),
('pma-analogy-test',46,'pma-letter-analogy','MAY : 3 :: OCTOBER : ?', 'EASY','LOW','5','6','7','8','C','The number represents the count of letters in the month name: MAY has three, and OCTOBER has seven.','null'::jsonb),
('pma-analogy-test',47,'pma-relationship-analogy','Jury : Verdict :: Committee : ?', 'MEDIUM','LOW','Recommendation','Meeting','Member','Chairperson','A','A jury reaches a verdict; a committee can produce a recommendation. The relation is group to formal conclusion.','null'::jsonb),
('pma-analogy-test',48,'pma-word-analogy','Lukewarm : Tepid :: Freezing : ?', 'MEDIUM','LOW','Cold','Hot','Wet','Mild','A','Lukewarm and tepid both mean moderately warm; freezing describes extreme cold, so cold is the closest match.','null'::jsonb),
('pma-analogy-test',49,'pma-relationship-analogy','Embargo : Trade :: Curfew : ?', 'MEDIUM','LOW','Movement','Communication','Assembly','Transport','A','An embargo restricts trade; a curfew restricts movement during specified hours.','null'::jsonb),
