update pma_seed_questions question
set priority = override.priority
from priority_overrides override
where question.paper_slug = override.paper_slug
  and question.question_number = override.question_number;

insert into public.topics (subject_id, name, slug, description, difficulty, is_active)
select subject.id,
       initcap(replace(replace(raw.topic_slug, 'pma-', ''), '-', ' ')),
       raw.topic_slug,
       'PMA Long Course initial-test reasoning practice topic.',
       'MEDIUM', true
from (select distinct topic_slug, paper_slug from pma_seed_questions) raw
join public.subjects subject on subject.slug = case
  when raw.paper_slug like 'pma-verbal-intelligence-test-%' then 'verbal-intelligence'
  when raw.paper_slug like 'pma-non-verbal-intelligence-test-%' then 'non-verbal-intelligence'
  when raw.paper_slug = 'pma-analogy-test' then 'analytical-reasoning'
  else 'mathematics'
end
on conflict (subject_id, slug) do update set
  name = excluded.name,
  description = excluded.description,
  is_active = true,
  updated_at = now();

with paper_subjects as (
  select paper_slug,
         case
           when paper_slug like 'pma-verbal-intelligence-test-%' then 'verbal-intelligence'
           when paper_slug like 'pma-non-verbal-intelligence-test-%' then 'non-verbal-intelligence'
           when paper_slug = 'pma-analogy-test' then 'analytical-reasoning'
           else 'mathematics'
         end as subject_slug
  from (select distinct paper_slug from pma_seed_questions) papers
),
question_upserts as (
  insert into public.questions (
    subject_id, topic_id, question_text, question_type, difficulty,
    option_a, option_b, option_c, option_d, correct_option, explanation,
    source, source_url, is_verified, is_active, content_key, category,
    priority, source_type, source_reference, visual_data
  )
  select subject.id,
         topic.id,
         raw.question_text,
         case when raw.visual_data = 'null'::jsonb then 'MCQ' else 'NON_VERBAL' end,
         raw.difficulty,
         raw.option_a,
         raw.option_b,
         raw.option_c,
         raw.option_d,
         raw.correct_option,
         raw.explanation,
         'Original FaujPrep PMA-style practice variation',
         'https://gotest.com.pk/intelligence-test/',
         false,
         true,
         raw.paper_slug || '-q' || lpad(raw.question_number::text, 3, '0'),
         topic.name,
         raw.priority,
         'ORIGINAL_VARIATION',
         'Original FaujPrep variation based on public preparation-pattern categories documented by GoTest (https://gotest.com.pk/intelligence-test/) and StudySpur (https://studyspur.com/pma-long-course-158-verbal-intelligence/). Not an officially released Pakistan Army question.',
         nullif(raw.visual_data, 'null'::jsonb)
  from pma_seed_questions raw
  join paper_subjects mapping on mapping.paper_slug = raw.paper_slug
  join public.subjects subject on subject.slug = mapping.subject_slug
  join public.topics topic on topic.subject_id = subject.id and topic.slug = raw.topic_slug
  on conflict (content_key) where content_key is not null do update set
    subject_id = excluded.subject_id,
    topic_id = excluded.topic_id,
    question_text = excluded.question_text,
    question_type = excluded.question_type,
    difficulty = excluded.difficulty,
    option_a = excluded.option_a,
    option_b = excluded.option_b,
    option_c = excluded.option_c,
    option_d = excluded.option_d,
    correct_option = excluded.correct_option,
    explanation = excluded.explanation,
    source = excluded.source,
    source_url = excluded.source_url,
    is_verified = excluded.is_verified,
    is_active = excluded.is_active,
    category = excluded.category,
    priority = excluded.priority,
    source_type = excluded.source_type,
    source_reference = excluded.source_reference,
    visual_data = excluded.visual_data,
    updated_at = now()
  returning id, content_key
)
select count(*) from question_upserts;

delete from public.mock_test_questions link
using public.mock_tests paper
where link.mock_test_id = paper.id
  and paper.slug in (
    'pma-verbal-intelligence-test-1', 'pma-verbal-intelligence-test-2',
    'pma-verbal-intelligence-test-3', 'pma-non-verbal-intelligence-test-1',
    'pma-non-verbal-intelligence-test-2', 'pma-non-verbal-intelligence-test-3',
    'pma-analogy-test', 'pma-mathematical-series-test'
  );

insert into public.mock_test_questions (mock_test_id, question_id, question_number)
select paper.id, question.id, raw.question_number
from pma_seed_questions raw
join public.mock_tests paper on paper.slug = raw.paper_slug
join public.questions question on question.content_key = raw.paper_slug || '-q' || lpad(raw.question_number::text, 3, '0')
on conflict (mock_test_id, question_id) do update set question_number = excluded.question_number;

do $$
declare
  v_paper_count integer;
  v_question_count integer;
  v_bad_papers integer;
  v_bad_questions integer;
begin
  select count(*) into v_paper_count
  from public.mock_tests
  where slug in (
    'pma-verbal-intelligence-test-1', 'pma-verbal-intelligence-test-2',
    'pma-verbal-intelligence-test-3', 'pma-non-verbal-intelligence-test-1',
    'pma-non-verbal-intelligence-test-2', 'pma-non-verbal-intelligence-test-3',
    'pma-analogy-test', 'pma-mathematical-series-test'
  );
  if v_paper_count <> 8 then raise exception 'Expected 8 PMA papers; found %', v_paper_count; end if;

  select count(*), count(distinct link.question_id)
    into v_question_count, v_bad_questions
  from public.mock_test_questions link
  join public.mock_tests paper on paper.id = link.mock_test_id
  where paper.slug like 'pma-%';
  if v_question_count <> 400 or v_bad_questions <> 400 then
    raise exception 'Expected 400 unique linked PMA questions; found % links and % unique', v_question_count, v_bad_questions;
  end if;

  select count(*) into v_bad_papers
  from public.mock_tests paper
  left join public.mock_test_questions link on link.mock_test_id = paper.id
  where paper.slug like 'pma-%'
  group by paper.id
  having count(link.question_id) <> 50
      or count(distinct link.question_number) <> 50
      or min(link.question_number) <> 1
      or max(link.question_number) <> 50;
  if coalesce(v_bad_papers, 0) <> 0 then raise exception 'One or more PMA papers do not contain question numbers 1 through 50'; end if;

  select count(*) into v_bad_questions
  from public.mock_tests paper
  join public.mock_test_questions link on link.mock_test_id = paper.id
  join public.questions question on question.id = link.question_id
  where paper.slug like 'pma-%'
    and (question.correct_option not in ('A','B','C','D')
      or nullif(trim(question.explanation), '') is null
      or question.priority not in ('HIGH','MEDIUM','LOW')
      or question.source_type <> 'ORIGINAL_VARIATION'
      or nullif(trim(question.source_reference), '') is null
      or nullif(trim(question.option_a), '') is null
      or nullif(trim(question.option_b), '') is null
      or nullif(trim(question.option_c), '') is null
      or nullif(trim(question.option_d), '') is null
      or lower(trim(question.option_a)) in (lower(trim(question.option_b)), lower(trim(question.option_c)), lower(trim(question.option_d)))
      or lower(trim(question.option_b)) in (lower(trim(question.option_c)), lower(trim(question.option_d)))
      or lower(trim(question.option_c)) = lower(trim(question.option_d))
      or question.content_key <> paper.slug || '-q' || lpad(link.question_number::text, 3, '0')
      or (paper.slug like 'pma-non-verbal-%' and (
        jsonb_typeof(question.visual_data) <> 'object'
        or jsonb_typeof(question.visual_data->'prompt') <> 'array'
        or jsonb_typeof(question.visual_data->'options') <> 'array'
        or jsonb_array_length(question.visual_data->'options') <> 4
      )));
  if v_bad_questions <> 0 then raise exception '% PMA questions failed completeness checks', v_bad_questions; end if;

  if (select count(*) from public.mock_tests where slug like 'pma-%' and category = 'Verbal Intelligence') <> 3
    or (select count(*) from public.mock_tests where slug like 'pma-%' and category = 'Non-Verbal Intelligence') <> 3
    or (select count(*) from public.mock_tests where slug like 'pma-%' and category = 'Analogy') <> 1
    or (select count(*) from public.mock_tests where slug like 'pma-%' and category = 'Mathematical Series') <> 1 then
    raise exception 'PMA paper category totals are incorrect';
  end if;

  if (select count(*) from public.mock_tests where slug like 'pma-%' and is_active = true and is_premium = false) <> 8 then
    raise exception 'All eight PMA papers must be active and available under the existing free-access policy';
  end if;

  if exists (
    select 1
    from public.mock_tests paper
    join public.mock_test_questions link on link.mock_test_id = paper.id
    join public.questions question on question.id = link.question_id
    where paper.slug like 'pma-%'
    group by regexp_replace(regexp_replace(lower(trim(question.question_text)), '[[:punct:]]+', ' ', 'g'), '[[:space:]]+', ' ', 'g')
    having count(*) > 1
  ) then raise exception 'Duplicate normalized PMA question text found'; end if;
end;
$$;

commit;

